/etc/rsyslog.d/44-managed-runtime.conf:
# Runtime output uses five fixed destinations, never a message-derived filename.
# Each field is JSON-escaped, including embedded newlines/control characters.
# Do not serialize the whole journal object: _CMDLINE and other fields may carry
# credentials. Program names are routing hints, not authentication boundaries.
template(name="ManagedRuntimeJSON" type="list" option.caseSensitive="on") {
  constant(value="{")
  property(name="timereported" outname="timestamp" format="jsonf" dateFormat="rfc3339")
  constant(value=",")
  property(name="hostname" outname="host" format="jsonf")
  constant(value=",")
  property(name="programname" outname="program" format="jsonf")
  constant(value=",")
  property(name="procid" outname="pid" format="jsonf")
  constant(value=",")
  property(name="syslogseverity-text" outname="severity" format="jsonf")
  constant(value=",")
  property(name="inputname" outname="input" format="jsonf")
  constant(value=",")
  property(name="$!_UID" outname="uid" format="jsonf")
  constant(value=",")
  property(name="$!_SYSTEMD_UNIT" outname="system_unit" format="jsonf")
  constant(value=",")
  property(name="$!_SYSTEMD_USER_UNIT" outname="user_unit" format="jsonf")
  constant(value=",")
  property(name="$!_TRANSPORT" outname="transport" format="jsonf")
  constant(value=",")
  property(name="$!metadata!filename" outname="source_file" format="jsonf")
  constant(value=",")
  property(name="msg" outname="message" format="jsonf")
  constant(value="}\n")
}

template(name="ManagedRuntimePath" type="list") {
  constant(value="/var/log/managed/")
  property(name="$.managed_category" securePath="replace")
  constant(value="/runtime.log")
}

if ($.managed_security_routed != "on") then {
  set $.managed_identity = tolower($programname & " " & $!_SYSTEMD_UNIT & " " & $!_SYSTEMD_USER_UNIT);
  # UNIT/USER_UNIT are not trusted journal fields. Use them only for records
  # actually attributed by journald to the systemd executable, never raw syslog.
  if ($inputname == "imjournal" and ($!_EXE == "/usr/lib/systemd/systemd" or $!_EXE == "/lib/systemd/systemd")) then {
    set $.managed_identity = $.managed_identity & " " & tolower($!UNIT & " " & $!USER_UNIT);
  }
  set $.managed_category = "system";
  if re_match($.managed_identity, "(^|[ /-])(apparmor|auditd|auth|sshd|sudo|su|polkitd|pam|chkrootkit|clamav|clamd|freshclam|fangfrisch|clamscan|debsecan|debsums|fail2ban|lynis|rkhunter|spectre-meltdown|crowdsec|nftables|nft)([.@ /-]|$)") then {
    set $.managed_category = "security";
  } else if re_match($.managed_identity, "(^|[ /-])(openai|chatgpt|codex|llama|whisper|ollama|vllm)([.@ /-]|$)") then {
    set $.managed_category = "models";
  } else if re_match($.managed_identity, "(^|[ /-])(waybar|crystal-dock|satty|wayscriber|gtkgreet|greetd|tomat|taskview|waypaper|swaybg|swaylock|fuzzel|mako|swayidle|wl-clip-persist|wl-paste|cliphist|kanshi|wlr-randr)([.@ /-]|$)") then {
    set $.managed_category = "desktop";
  } else if re_match($.managed_identity, "(^|[ /-])(networkmanager|networkd|resolved|wpa_supplicant|iwd|dhclient|dhcpcd|bluetoothd|bluetooth|udevd|udisksd|udisks2|upowerd|upower|pipewire|wireplumber|pulseaudio|rtkit-daemon|fwupd|mullvad-daemon|zram|zswap|timeshift|thermald|power-profiles-daemon|smartd|fstrim|systemd-logind)([.@ /-]|$)") then {
    set $.managed_category = "system";
  } else if re_match($.managed_identity, "(^|[ /-])(tuta|tutanota|bitwarden|keepassxc|thunar|sleek|featherpad|spotify|mpv|focuswriter|gnumeric|firefox|chromium|chrome|google-chrome|microsoft-edge|edge|brave|vivaldi|librewolf|floorp|zen|tor-browser|browser|obsidian|code|vscode|vscodium|codium|filen|qoredb|retroarch|sqlitebrowser|zoom|discord|wallet|liferea|telegram|mullvad-vpn|adb|android-debug-bridge|postman|ledger-live|qbittorrent)([.@ /-]|$)") then {
    set $.managed_category = "apps";
  } else if re_match($.managed_identity, "(^|[ /])labwc-(wayland|electron)-") then {
    # The existing managed launcher also covers future applications.
    set $.managed_category = "apps";
  } else if re_match($.managed_identity, "(^|[ /])labwc([.@ /-]|$)") then {
    set $.managed_category = "desktop";
  } else if ($!_SYSTEMD_USER_UNIT != "" or $!_SYSTEMD_UNIT startswith "user@" or $!_SYSTEMD_UNIT startswith "session-") then {
    set $.managed_category = "apps";
  }
  action(type="omfile" dynaFile="ManagedRuntimePath" template="ManagedRuntimeJSON"
         dynaFileCacheSize="5" fileOwner="root" fileGroup="adm" fileCreateMode="0640"
         dirOwner="root" dirGroup="adm" dirCreateMode="0750" createDirs="off"
         action.resumeRetryCount="-1" action.resumeInterval="10"
         queue.type="LinkedList" queue.filename="managed-runtime"
         queue.size="1000" queue.highWatermark="800" queue.lowWatermark="200"
         queue.maxDiskSpace="64m" queue.maxFileSize="8m" queue.saveOnShutdown="on")
  set $.managed_security_routed = "on";
}
